using Astronomy.MediaFactory.Core.KnowledgeFoundation; using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeVersionFilterTests{[Fact]public void Supports_exact_min_max_and_range(){Assert.Equal(new KnowledgeVersion(2),new AstronomyKnowledgeVersionFilter(new KnowledgeVersion(2)).ExactRevision);Assert.Equal(new KnowledgeVersion(2),new AstronomyKnowledgeVersionFilter(minimumRevision:new KnowledgeVersion(2)).MinimumRevision);Assert.Equal(new KnowledgeVersion(3),new AstronomyKnowledgeVersionFilter(maximumRevision:new KnowledgeVersion(3)).MaximumRevision);var r=new AstronomyKnowledgeVersionFilter(null,new KnowledgeVersion(2),new KnowledgeVersion(3));Assert.Equal(new KnowledgeVersion(2),r.MinimumRevision);Assert.Equal(new KnowledgeVersion(3),r.MaximumRevision);}[Fact]public void Rejects_invalid_combinations(){Assert.Throws<ArgumentOutOfRangeException>(()=>new KnowledgeVersion(0));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeVersionFilter(new KnowledgeVersion(1),new KnowledgeVersion(1)));Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgeVersionFilter(null,new KnowledgeVersion(3),new KnowledgeVersion(2)));}[Fact]public void Empty_filter_is_explicit_and_equal(){Assert.True(new AstronomyKnowledgeVersionFilter().IsEmpty);Assert.Equal(new AstronomyKnowledgeVersionFilter(),new AstronomyKnowledgeVersionFilter());}}
